try {
    $stmt = $pdo->prepare('DELETE FROM autores WHERE id_autor = ?');
    $stmt->execute([(int) ($_POST['id_autor'] ?? 0)]);
    mensagem('sucesso', 'Autor apagado.');
} catch (PDOException $e) {
